248	    /**
249	     * Rejects an owner payload that is missing or blank in any required field. Bean Validation
250	     * already rejects {@code null} values and some formats, but a whitespace-only value can still
251	     * satisfy a {@code @Size(min = 1)} constraint; this guard catches those remaining cases.
252	     *
253	     * @param ownerFieldsDto the submitted owner fields
254	     * @throws InvalidOwnerFieldsException if any required field is missing or blank, carrying the
255	     *                                     name of every offending field
256	     */
257	    private void validateRequiredFields(OwnerFieldsDto ownerFieldsDto) {
258	        List<String> missingFields = new ArrayList<>();
259	        if (isBlank(ownerFieldsDto.getFirstName())) {
260	            missingFields.add("firstName");
261	        }
262	        if (isBlank(ownerFieldsDto.getLastName())) {
263	            missingFields.add("lastName");
264	        }
265	        if (isBlank(normalizeAddress(ownerFieldsDto.getAddress()))) {
266	            missingFields.add("address");
267	        }
268	        if (isBlank(ownerFieldsDto.getCity())) {
269	            missingFields.add("city");
270	        }
271	        if (isBlank(ownerFieldsDto.getTelephone())) {
272	            missingFields.add("telephone");
273	        }
274	        if (!missingFields.isEmpty()) {
275	            throw new InvalidOwnerFieldsException(missingFields);
276	        }
277	    }
278	
279	    private boolean isBlank(String value) {
280	        return value == null || value.isBlank();
281	    }
282	
283	    /**
284	     * Normalizes a telephone number for owner creation into E.164 form. Spaces, dashes and brackets
285	     * are stripped. When the value carries a leading {@code '+'} the country code it supplies is kept;
286	     * otherwise the number is treated as a national Australian number, so a single leading {@code '0'}
287	     * is dropped and the {@code '+61'} country code is prepended. The result must be a {@code '+'}
288	     * followed by 8 to 15 digits. This E.164 string is what gets stored and returned.
289	     *
290	     * @param telephone the raw telephone value submitted by the client
291	     * @return the telephone in E.164 form, e.g. {@code +61412345678}
292	     * @throws InvalidOwnerFieldsException if the value cannot form a valid E.164 number, yielding a
293	     *                                     400 response
294	     */
295	    private String normalizeTelephone(String telephone) {
296	        String e164 = toE164(telephone);
297	        if (e164 == null) {
298	            throw new InvalidOwnerFieldsException(List.of("telephone"));
299	        }
300	        return e164;
301	    }
302	
303	    /**
304	     * Converts a raw telephone value to E.164 form, or returns {@code null} if it cannot form a valid
305	     * E.164 number. Spaces, dashes and brackets are removed; a leading {@code '+'} keeps the supplied
306	     * country code, while a bare national number has a single leading {@code '0'} dropped and the
307	     * {@code '+61'} country code prepended. A valid result is a {@code '+'} followed by 8 to 15 digits.
308	     *
309	     * @param telephone the raw telephone value, possibly {@code null}
310	     * @return the E.164 string, or {@code null} if the value is not a valid E.164 number
311	     */
312	    private String toE164(String telephone) {
313	        if (telephone == null) {
314	            return null;
315	        }
316	        String cleaned = telephone.replaceAll("[\\s()\\-]", "");
317	        boolean hasPlus = cleaned.startsWith("+");
318	        String digits = (hasPlus ? cleaned.substring(1) : cleaned).replaceAll("\\D", "");
319	        String nationalSignificant = hasPlus
320	            ? digits
321	            : "61" + (digits.startsWith("0") ? digits.substring(1) : digits);
322	        if (!nationalSignificant.matches("[0-9]{8,15}")) {
323	            return null;
324	        }
325	        return "+" + nationalSignificant;
326	    }
327	
328	    /**
329	     * Normalizes an optional owner email address. A {@code null} value means the field was omitted and
330	     * is left unset. When a value is present it must be a syntactically valid address; the stored and
331	     * returned value is that address lower-cased.
332	     *
333	     * @param email the raw email value submitted by the client, or {@code null} if omitted
334	     * @return the lower-cased email, or {@code null} if none was supplied
335	     * @throws InvalidOwnerFieldsException if a value is present but not a syntactically valid address,
336	     *                                     yielding a 400 response
337	     */
338	    private String normalizeEmail(String email) {
339	        if (email == null) {
340	            return null;
341	        }
342	        if (!EMAIL_PATTERN.matcher(email).matches()) {
343	            throw new InvalidOwnerFieldsException(List.of("email"));
344	        }
345	        return email.toLowerCase(Locale.ROOT);
346	    }
347	
348	    /**
349	     * Builds the owner's {@code customerCode}, formatted {@code '<LAST3>-<NNNN>'}. {@code LAST3} is
350	     * the upper-cased first three letters of the last name, and {@code NNNN} is a global 4-digit
351	     * zero-padded sequence equal to one more than the current number of owners (e.g. {@code 'SMI-0007'}).
352	     *
353	     * @param lastName the owner's last name
354	     * @return the formatted customer code
355	     */
356	    private String generateCustomerCode(String lastName) {
357	        String letters = lastName.replaceAll("[^\\p{L}]", "");
358	        String last3 = letters.substring(0, Math.min(3, letters.length())).toUpperCase(Locale.ROOT);
359	        int sequence = this.clinicService.findAllOwners().size() + 1;
360	        return String.format("%s-%04d", last3, sequence);
361	    }
362	
363	    /**
364	     * Rejects creation of an owner whose E.164 telephone is already used by any other owner. Stored
365	     * telephones are converted to E.164 here as well so the comparison is independent of the format
366	     * each owner was originally saved with; a stored value that cannot form a valid E.164 number is
367	     * ignored rather than matched.
368	     *
369	     * @param telephone the E.164 telephone of the owner being created
370	     * @throws DuplicateOwnerTelephoneException if another owner already uses this telephone,
371	     *                                          yielding a 409 Conflict response
372	     */
373	    private void rejectDuplicateTelephone(String telephone) {
374	        boolean inUse = this.clinicService.findAllOwners().stream()
375	            .map(Owner::getTelephone)
376	            .map(this::toE164)
377	            .anyMatch(telephone::equals);
378	        if (inUse) {
379	            throw new DuplicateOwnerTelephoneException(telephone);
380	        }
381	    }
382	
383	    /**
384	     * Rejects creation of an owner whose last name and address both match an existing owner's,
385	     * which marks them as belonging to the same household. Both the last name and the address are
386	     * compared case-insensitively with surrounding and internal whitespace collapsed, so values
387	     * that differ only in letter case or spacing are still treated as a match.
388	     *
389	     * @param lastName the last name of the owner being created
390	     * @param address  the address of the owner being created
391	     * @throws DuplicateOwnerHouseholdException if another owner already shares this last name and
392	     *                                          address, yielding a 409 Conflict response
393	     */
394	    private void rejectDuplicateHousehold(String lastName, String address) {
395	        if (!findHouseholdMembers(lastName, address).isEmpty()) {
396	            throw new DuplicateOwnerHouseholdException(lastName, address);
397	        }
398	    }
399	
400	    /**
401	     * Finds every existing owner belonging to the household identified by the given last name and
402	     * address — that is, the owners the duplicate-household rule rejects and the {@code sharesHousehold}
403	     * opt-in joins. Both the last name and the address are compared case-insensitively with surrounding
404	     * and internal whitespace collapsed, so values that differ only in letter case or spacing still
405	     * match. This single definition of household membership is shared by {@link #rejectDuplicateHousehold}
406	     * and {@link #assignHousehold}.
407	     *
408	     * @param lastName the last name of the owner being created
409	     * @param address  the address of the owner being created
410	     * @return the existing owners in that household, or an empty list if there are none
411	     */
412	    private List<Owner> findHouseholdMembers(String lastName, String address) {
413	        String normalizedLastName = normalizeForComparison(lastName);
414	        String normalizedAddress = normalizeAddress(address);
415	        return this.clinicService.findAllOwners().stream()
416	            .filter(existing -> normalizeForComparison(existing.getLastName()).equals(normalizedLastName)
417	                && normalizeAddress(existing.getAddress()).equals(normalizedAddress))
418	            .toList();
419	    }
420	
421	    /**
422	     * Enrolls a newly created owner into the household of any existing owner that shares its last
423	     * name and address, so an owner that opts in via {@code sharesHousehold} is accepted instead of
424	     * rejected as a duplicate. Last name and address are compared case-insensitively with collapsed
425	     * whitespace. When at least one such owner already exists, every member of the household — the
426	     * existing owners and the new one — is assigned the same stable {@code householdId}; if a member
427	     * already carries one it is reused, otherwise a new identifier derived from the shared last name
428	     * and address is created and back-filled onto the existing members. When no owner yet lives at
429	     * that address under the same last name no identifier is assigned and the owner is created alone.
430	     *
431	     * @param newOwner the owner being created, whose {@code householdId} will be set on a match
432	     * @param lastName the last name of the owner being created
433	     * @param address  the address of the owner being created
434	     * @return the assigned {@code householdId}, or {@code null} if there was no household to join
435	     */
436	    private String assignHousehold(Owner newOwner, String lastName, String address) {
437	        List<Owner> members = findHouseholdMembers(lastName, address);
438	        if (members.isEmpty()) {
439	            return null;
440	        }
441	        String householdId = members.stream()
442	            .map(Owner::getHouseholdId)
443	            .filter(existing -> existing != null && !existing.isBlank())
444	            .findFirst()
445	            .orElseGet(() -> generateHouseholdId(normalizeForComparison(lastName), normalizeAddress(address)));
446	        for (Owner member : members) {
447	            if (member.getHouseholdId() == null || member.getHouseholdId().isBlank()) {
448	                member.setHouseholdId(householdId);
449	                this.clinicService.saveOwner(member);
450	            }
451	        }
452	        newOwner.setHouseholdId(householdId);
453	        return householdId;
454	    }
455	
456	    /**
457	     * Derives a stable household identifier, formatted {@code 'HH-<HEX12>'}, where {@code HEX12} is
458	     * the first twelve upper-cased hex characters of the SHA-256 digest of the normalized last name
459	     * and address joined by a {@code '|'}. The same last name and address therefore always yield the
460	     * same identifier, so members of one household share a single value.
461	     *
462	     * @param normalizedLastName the household's last name, already normalized for comparison
463	     * @param normalizedAddress  the household's address, already normalized for comparison
464	     * @return the derived household identifier
465	     */
466	    private String generateHouseholdId(String normalizedLastName, String normalizedAddress) {
467	        try {
468	            byte[] digest = MessageDigest.getInstance("SHA-256")
469	                .digest((normalizedLastName + "|" + normalizedAddress).getBytes(StandardCharsets.UTF_8));
470	            StringBuilder hex = new StringBuilder(digest.length * 2);
471	            for (byte b : digest) {
472	                hex.append(String.format("%02x", b));
473	            }
474	            return "HH-" + hex.substring(0, 12).toUpperCase(Locale.ROOT);
475	        } catch (NoSuchAlgorithmException e) {
476	            throw new IllegalStateException("SHA-256 algorithm not available", e);
477	        }
478	    }
479	
480	    /**
481	     * Normalizes a text value for case- and whitespace-insensitive comparison: surrounding
482	     * whitespace is trimmed, every internal run of whitespace is collapsed to a single space, and
483	     * the result is lower-cased.
484	     *
485	     * @param value the value to normalize, possibly {@code null}
486	     * @return the normalized value, or an empty string if {@code value} is {@code null}
487	     */
488	    private String normalizeForComparison(String value) {
489	        if (value == null) {
490	            return "";
491	        }
492	        return value.trim().replaceAll("\\s+", " ").toLowerCase(Locale.ROOT);
493	    }
494	
495	    /**
496	     * Normalizes an owner address for storage, display and comparison. Surrounding whitespace is
497	     * trimmed, every internal run of whitespace is collapsed to a single space, the value is
498	     * upper-cased, and common street-type abbreviations appearing as whole tokens are expanded
499	     * ({@code ST} to {@code STREET}, {@code RD} to {@code ROAD}, {@code AVE} to {@code AVENUE}).
500	     * This normalized value is what gets stored and returned, and it is the form every address
501	     * comparison (household duplicate detection and the shared household id) uses.
502	     *
503	     * @param address the raw address value submitted by the client, possibly {@code null}
504	     * @return the normalized address, or an empty string if {@code address} is {@code null}
505	     */
506	    private String normalizeAddress(String address) {
507	        if (address == null) {
508	            return "";
509	        }
510	        String collapsed = address.trim().replaceAll("\\s+", " ").toUpperCase(Locale.ROOT);
511	        if (collapsed.isEmpty()) {
512	            return collapsed;
513	        }
514	        String[] tokens = collapsed.split(" ");
515	        StringBuilder normalized = new StringBuilder(collapsed.length());
516	        for (int i = 0; i < tokens.length; i++) {
517	            if (i > 0) {
518	                normalized.append(' ');
519	            }
520	            normalized.append(ADDRESS_ABBREVIATIONS.getOrDefault(tokens[i], tokens[i]));
521	        }
522	        return normalized.toString();
523	    }
524	}
